const body = $json.body ?? $json;
const CONFIG = {
  "wiki_node_token": "YOUR_WIKI_NODE_TOKEN",
  "table_id": "YOUR_TABLE_ID",
  "worker_base_url": "https://YOUR_WORKER_HOST",
  "google_drive_folder_id": "YOUR_DRIVE_FOLDER_ID",
  "poll_timeout_seconds": 6000
};
const recordId = body.record_id ?? body.recordId ?? body.data?.record_id ?? body.data?.recordId;
if (typeof recordId !== 'string' || !/^rec[A-Za-z0-9]+$/.test(recordId)) throw new Error('Missing or invalid record_id');
for (const [key, value] of Object.entries(CONFIG)) {
  if (typeof value === 'string' && value.includes('YOUR_')) throw new Error('Configure ' + key + ' first');
}
if (!/^https:\/\/[^/]+/.test(CONFIG.worker_base_url)) throw new Error('Worker requires an HTTPS URL');
return [{json: {...CONFIG, record_id: recordId}}];

const cfg = $('CONFIG1').first().json;
const token = $('Get Feishu Tenant Token1').first().json.tenant_access_token;

const api = $json;

if (api.code !== undefined && api.code !== 0) {
  throw new Error(
    `飞书读取记录失败 code=${api.code}, msg=${api.msg || ''}`
  );
}

const record = api.data?.record ?? api.data ?? api.record ?? api;
const fields = record.fields ?? {};
const recordId = record.record_id ?? cfg.record_id;

const asAttachments = (value) => {
  return Array.isArray(value)
    ? value.filter(Boolean)
    : [];
};

const asText = (value) => {
  if (value === null || value === undefined) {
    return "";
  }

  if (
    typeof value === "string" ||
    typeof value === "number"
  ) {
    return String(value);
  }

  if (Array.isArray(value)) {
    return value
      .map((item) => {
        if (
          typeof item === "string" ||
          typeof item === "number"
        ) {
          return String(item);
        }

        return (
          item?.text ??
          item?.name ??
          item?.value ??
          ""
        );
      })
      .filter(Boolean)
      .join(", ");
  }

  return (
    value?.text ??
    value?.name ??
    value?.value ??
    ""
  );
};

const sequence = asText(fields["序号"]);

const templateVideos = asAttachments(
  fields["模板视频"]
);

const referenceImages = asAttachments(
  fields["人物参考图"]
).slice(0, 3);

const genderRaw = asText(
  fields["人物性别"]
);

const currentStatus = asText(
  fields["状态"]
);

if (currentStatus === '生成中') return [{json: {skip_duplicate: true, record_id: recordId}}];
let validationError = "";

if (!templateVideos.length) {
  validationError = "缺少模板视频";
} else if (!referenceImages.length) {
  validationError = "缺少人物参考图";
} else if (!genderRaw) {
  validationError = "缺少人物性别";
}

const templateVideo = templateVideos[0];

const normalizedGender = genderRaw
  .trim()
  .toLowerCase();

const isFemale =
  normalizedGender.includes("female") ||
  normalizedGender.includes("woman") ||
  genderRaw.includes("女");

const gender = isFemale
  ? "Female"
  : "Male";


const refTags = referenceImages
  .map((_, index) => `<IMAGE_REF_${index}>`)
  .join(", ");

const primaryRefTag = referenceImages.length
  ? "<IMAGE_REF_0>"
  : "the primary visual reference";

const secondaryRefTags = referenceImages
  .slice(1)
  .map(
    (_, index) =>
      `<IMAGE_REF_${index + 1}>`
  )
  .join(", ");

const refNames = referenceImages
  .map((item, index) => {
    const name =
      item?.name ||
      item?.file_token ||
      `reference_${index}`;

    return `${index}: ${name}`;
  })
  .join("; ");

const secondaryReferenceInstruction =
  secondaryRefTags
    ? `Use ${secondaryRefTags} only as additional references for profile angles and body proportions.`
    : "";

const promptTemplate = `
VIDEO CHARACTER APPEARANCE EDIT

Production:
- Source: ${templateVideo?.name || "N/A"}
- Character gender: ${gender}
- Visual references: ${refNames || "N/A"}
- Segment: {{SEGMENT_INDEX}} of {{SEGMENT_COUNT}}
- Duration: {{SEGMENT_DURATION}} seconds

TASK:
Use the supplied video segment as the base footage.
Update the visual appearance of the primary adult performer so that the same consistent character shown in ${refTags} appears throughout the segment.
Use the reference images only as visual guides. Do not use them as literal video frames.

REFERENCE PRIORITY:
Use ${primaryRefTag} as the main reference for facial appearance, hairstyle, hair length, hair color, hairline, clothing, clothing colors, glasses, makeup, facial hair, and accessories.
${secondaryReferenceInstruction}
If the references differ, always follow ${primaryRefTag}.
Do not combine different outfits, hairstyles, or accessories.

CHARACTER CONSISTENCY:
Keep the character visually consistent in every frame:
- same facial appearance and facial proportions
- same age appearance and skin tone
- same hairstyle, hair length, hair color, and hairline
- same clothing, clothing colors, collar, sleeves, and visible layers
- same glasses, makeup, facial hair, and accessories
- same body proportions

The hairstyle and clothing shown in ${primaryRefTag} must remain unchanged.
Keep the same character during head turns, profile views, body movement, partial occlusion, lighting changes, camera movement, and scene changes.
Avoid appearance drift or sudden visual changes between frames.

SOURCE PRESERVATION:
Preserve the source video's:
- pose and movement
- hand gestures
- performance timing
- camera movement
- composition and framing
- scene and background
- lighting and objects
- cuts and transitions
- on-screen text

Preserve the exact crop, aspect ratio, field of view, camera distance, lens perspective, subject position, head size, and body scale.
Do not add zooms, crop changes, reframing, stretching, or subject enlargement unless already present in the source.
Do not turn a medium shot into a close-up.
Do not add people, objects, text, logos, or backgrounds.
Keep unrelated visual elements unchanged.

VISUAL STABILITY:
Maintain natural and stable eyes, mouth, teeth, jaw, ears, glasses, neck, shoulders, hands, and fingers.
Avoid warped features, duplicated features, unstable glasses, oversized heads, distorted mouths, malformed hands, and changing body proportions.
Prioritize character consistency, stable anatomy, original framing, and original movement.

AUDIO:
Edit the visual track only. Do not synthesize, replace, translate, or alter speech.
The original source audio will be preserved separately, with its original timing.

CONTINUITY:
This segment is part of a longer video.
Across all segments, maintain the same facial appearance, hairstyle, clothing, colors, glasses, accessories, body proportions.
Keep segment boundaries visually and audibly compatible.
Avoid wardrobe changes, hairstyle changes, appearance drift, sudden zooms, crop changes, scale changes.

Return the edited video segment while preserving the structure and timing of the source footage.
`.trim();

if (promptTemplate.length > 5000) {
  throw new Error(
    `提示词长度为 ${promptTemplate.length} 个字符，超过 Worker 的 5000 字符限制`
  );
}

return [
  {
    json: {
      record_id: recordId,
      sequence,
      current_status: currentStatus,
      validation_error: validationError,

      table_id: cfg.table_id,

      app_token:
        $('Get Wiki Bitable Token1')
          .first()
          .json
          .data
          .node
          .obj_token,

      template_video: templateVideo,
      reference_images: referenceImages,

      target_gender: gender,

      prompt_template: promptTemplate,

      worker_base_url:
        cfg.worker_base_url.replace(
          /\/+$/,
          ""
        ),

      google_drive_folder_id:
        cfg.google_drive_folder_id,

      feishu_access_token:
        token
    }
  }
];

const data = $('Build Task & Prompt1').first().json;
return [{json: {
  source_url: data.template_video.url,
  reference_image_urls: data.reference_images.map(item => item.url),
  segment_seconds: 10,
  prompt: data.prompt_template,
  external_id: data.record_id,
  feishu_access_token: data.feishu_access_token,
  generate_audio: false,
  resolution: "720p", generate_metadata: true, publishing_platform: "short_video", caption_language: "zh-CN"
}}];

const ctx = $('Remember Job').first().json;
const timeout = Number($('CONFIG1').first().json.poll_timeout_seconds);
if (!Number.isFinite(ctx.poll_started_at_ms) || !(timeout > 0)) throw new Error('Invalid polling clock');
const status = String($json.status ?? '').trim().toLowerCase();
const elapsedSeconds = Math.max(0, (Date.now() - ctx.poll_started_at_ms) / 1000);
const isCompleted = status === 'completed';
const isFailed = ['failed', 'cancelled', 'canceled', 'expired'].includes(status);
const isTimedOut = !isCompleted && !isFailed && elapsedSeconds >= timeout;
return [{json: {...$json, elapsed_seconds: elapsedSeconds, is_completed: isCompleted,
  is_failed: isFailed, is_timed_out: isTimedOut,
  public_error: isTimedOut ? '等待超时；后台任务可能仍在运行，请先核查再重试。'
    : isFailed ? '视频处理失败；请在 Worker 查看任务详情。' : ''}}];

if (typeof $json.job_id !== 'string' || !/^[A-Za-z0-9_-]+$/.test($json.job_id)) {
  throw new Error('Worker accepted no usable job_id; check worker before submitting again');
}
return [{json: {job_id: $json.job_id, poll_started_at_ms: Date.now()}}];

if (Number($json.code) !== 0) throw new Error('Feishu API rejected the request');
if (typeof $json.tenant_access_token !== 'string' || !$json.tenant_access_token) throw new Error('Missing Feishu token');
return $input.all();

if (Number($json.code) !== 0) throw new Error('Feishu API rejected the request');
if (!$json.data?.node?.obj_token) throw new Error('Missing Bitable token');
return $input.all();

const cfg = $('CONFIG1').first().json;
let jobId = '';
try { jobId = $('Remember Job').first().json.job_id || ''; } catch (_) {}
return [{json: {record_id: cfg.record_id,
  error_message: '流程异常；执行 ' + String($execution.id) + (jobId ? '，任务 ' + jobId : '')
    + '。请先检查执行记录/后台任务，确认后再重试。'}}];

if (Number($json.code) !== 0) throw new Error('Feishu API rejected the request');
if (typeof $json.tenant_access_token !== 'string' || !$json.tenant_access_token) throw new Error('Missing Feishu token');
return $input.all();

if (Number($json.code) !== 0) throw new Error('Feishu API rejected the request');
if (!$json.data?.node?.obj_token) throw new Error('Missing Bitable token');
return $input.all();
